{% import "costeo_yelke/templates/print/oc_yelke.html" as oc %}
{#- Orden de maquila -- OC de subcontratación.

    Dentro, la OC lleva UN RENGLÓN POR PIEZA (frente, espalda, puños...) porque
    es lo que permite mover cada pieza por separado con el taller, y el precio
    del servicio viaja completo en una sola de ellas (las demás van en $0, ver
    _resolve_piece_states en costeo.py). Nada de eso le importa al taller: él
    cobra POR PRENDA.

    Aquí se reagrupa por servicio y producto: una línea, las prendas reales y el
    importe sumado, del que sale el precio por prenda. Las piezas que entran en
    cada servicio se listan debajo del nombre, como referencia de lo que entrega.

    OJO: las prendas NO son la suma de las cantidades -- los puños van 2 por
    prenda y darían el doble. Salen del campo `prendas` del renglón (patch
    v0_2_41). Un renglón sin ese campo se muestra tal cual. -#}
{{ oc.estilos() }}
<div class="pdf-container">

{{ oc.encabezado(doc, "Detalles de Orden de Maquila", true) }}

{%- set grupos = [] -%}
{%- set indice = {} -%}
{%- for it in doc.items -%}
  {%- set prendas = it.get("prendas") or 0 -%}
  {%- if prendas > 0 -%}
    {%- set clave = (it.get("producto_terminado") or "") ~ "||" ~ it.item_code -%}
    {%- if clave not in indice -%}
      {%- set _ = indice.update({clave: grupos|length}) -%}
      {%- set _ = grupos.append({
            "servicio": it.item_name or it.item_code, "codigo": it.item_code,
            "producto": it.get("producto_terminado") or "", "prendas": prendas,
            "importe": 0.0, "piezas": [], "uom": "prendas", "agrupado": true}) -%}
    {%- endif -%}
    {%- set g = grupos[indice[clave]] -%}
    {%- set _ = g.update({"importe": g["importe"] + (it.amount or 0)}) -%}
    {%- set fg = it.get("fg_item") or "" -%}
    {%- if " · " in fg -%}
      {%- set pz = fg.split(" · ")[-1] -%}
      {%- if pz not in g["piezas"] -%}{%- set _ = g["piezas"].append(pz) -%}{%- endif -%}
    {%- endif -%}
  {%- else -%}
    {%- set _ = grupos.append({
          "servicio": it.item_name or it.item_code, "codigo": it.item_code,
          "producto": "", "prendas": it.qty, "importe": it.amount or 0,
          "piezas": [], "uom": it.uom, "agrupado": false}) -%}
  {%- endif -%}
{%- endfor -%}

<table class="table items-table">
    <thead>
        <tr>
            <th class="text-center" width="5%">#</th>
            <th width="34%">Servicio</th>
            <th width="27%">Producto</th>
            <th class="text-right" width="10%">Cant.</th>
            <th class="text-right" width="12%">P. Unitario</th>
            <th class="text-right" width="12%">Importe</th>
        </tr>
    </thead>
    <tbody>
        {% for g in grupos %}
        <tr>
            <td class="text-center">{{ loop.index }}</td>
            <td>
                <strong class="item-title">{{ g.servicio }}</strong>
                {% if g.codigo and g.codigo != g.servicio %}
                    <div class="item-code"><strong>Código:</strong> {{ g.codigo }}</div>
                {% endif %}
                {% if g.piezas %}
                    <div class="item-pieces"><strong>Piezas:</strong> {{ g.piezas|join(", ") }}</div>
                {% endif %}
            </td>
            <td>{{ g.producto or "-" }}</td>
            <td class="text-right">
                {{ "{:,.0f}".format(g.prendas) if g.prendas == g.prendas|round(0) else "{:,.2f}".format(g.prendas) }}
                <div class="item-code">{{ g.uom }}</div>
            </td>
            <td class="text-right">
                {{ frappe.utils.fmt_money(g.importe / g.prendas, currency=doc.currency) if g.prendas else "-" }}
            </td>
            <td class="text-right">
                <strong>{{ frappe.utils.fmt_money(g.importe, currency=doc.currency) }}</strong>
            </td>
        </tr>
        {% endfor %}
    </tbody>
</table>

{{ oc.totales(doc) }}
{{ oc.cierre(doc) }}

{#- Orden de manufactura de ESTE taller: un registro por producto que trabaja, con la
    info general y tallas completas y solo lo que se le asignó en la OM general del
    costeo (om_general.om_de_oc, registrado como método jinja en hooks.py). -#}
{%- set oms = om_de_oc(doc.name) | selectattr("origen", "equalto", "general") | list -%}
{%- if oms -%}
{%- set campos = [("om_modelo", "Modelo"), ("om_tela", "Tela"), ("om_color", "Color"),
      ("om_color_principal", "Color principal"), ("om_forro", "Forro"), ("om_combinacion", "Combinación"),
      ("om_ubicacion", "Ubicación"), ("om_aberturas", "Aberturas"), ("om_fecha_requerida", "Fecha requerida")] -%}
{%- for r in oms %}
<div style="page-break-before: always;">
    <h4 class="payment-terms-title">Orden de manufactura · {{ r.item_name or r.producto }}</h4>
    <table class="table" style="margin-bottom: 8px;">
        <tbody>
        {%- set llenos = [] -%}
        {%- for f, l in campos -%}{%- if r.general.get(f) -%}{%- set _ = llenos.append((l, r.general.get(f))) -%}{%- endif -%}{%- endfor -%}
        {%- for fila in llenos|batch(2) %}
            <tr>
            {%- for l, v in fila %}
                <td width="18%"><strong>{{ l }}</strong></td>
                <td width="32%">{{ frappe.format_date(v) if l == "Fecha requerida" else v }}</td>
            {%- endfor %}
            {%- if fila|length == 1 %}<td></td><td></td>{% endif %}
            </tr>
        {%- endfor %}
        {%- set marcas = [] -%}
        {%- for f, l in [("om_bordado", "Bordado"), ("om_estampado", "Estampado"), ("om_sublimado", "Sublimado"), ("om_reflejante", "Reflejante")] -%}
            {%- if r.general.get(f) -%}{%- set _ = marcas.append(l) -%}{%- endif -%}
        {%- endfor -%}
        {%- if marcas %}
            <tr><td><strong>Lleva</strong></td><td colspan="3">{{ marcas|join(", ") }}</td></tr>
        {%- endif %}
        </tbody>
    </table>

    {%- if r.tallas %}
    <table class="table items-table" style="margin-bottom: 8px;">
        <thead><tr><th>Género</th><th>Talla</th><th class="text-right">Cantidad</th></tr></thead>
        <tbody>
        {%- for t in r.tallas %}
            <tr><td>{{ t.genero or "-" }}</td><td>{{ t.talla }}</td><td class="text-right">{{ "{:,.0f}".format(t.cantidad or 0) }}</td></tr>
        {%- endfor %}
            <tr><td colspan="2" class="text-right"><strong>Total</strong></td><td class="text-right"><strong>{{ "{:,.0f}".format(r.tallas|sum(attribute="cantidad")) }}</strong></td></tr>
        </tbody>
    </table>
    {%- endif %}

    {%- if r.procesos %}
    <table class="table items-table" style="margin-bottom: 8px;">
        <thead><tr><th width="40%">Proceso</th><th width="35%">Ubicación</th><th width="25%">Colores</th></tr></thead>
        <tbody>
        {%- for p in r.procesos %}
            <tr><td>{{ p.nombre_proceso or "" }}</td><td>{{ p.ubicacion or "" }}</td><td>{{ p.colores or "" }}</td></tr>
        {%- endfor %}
        </tbody>
    </table>
    {%- endif %}

    {%- if r.observaciones %}
    <div style="margin-bottom: 8px;">
        <strong>Observaciones</strong>
        {%- for o in r.observaciones %}
        <div style="white-space: pre-line; margin-top: 2px;">{{ o.texto }}</div>
        {%- endfor %}
    </div>
    {%- endif %}

    {%- for t in r.tablas %}
    <div style="margin-bottom: 8px;">
        <strong>{{ t.name }}</strong>{% if t.unit %} ({{ t.unit }}){% endif %}
        <table class="table" style="margin-top: 2px;">
            {%- for row in t.rows %}
            <tr>{% for c in t.columns %}<td class="text-center">{{ row.cells.get(c, "") }}</td>{% endfor %}</tr>
            {%- endfor %}
        </table>
    </div>
    {%- endfor %}

    {%- for a in r.archivos %}
    {%- set ext = (a.archivo or "").split("?")[0].split(".")[-1]|lower %}
    <div style="margin-bottom: 8px; page-break-inside: avoid;">
        {%- if ext in ["png", "jpg", "jpeg", "gif", "webp", "bmp", "svg"] %}
        <img src="{{ a.archivo }}" style="max-width: 100%; max-height: 420px;">
        {%- else %}
        <div>Archivo adjunto: {{ a.archivo }}</div>
        {%- endif %}
        {%- if a.descripcion %}<div class="item-code">{{ a.descripcion }}</div>{% endif %}
    </div>
    {%- endfor %}
</div>
{%- endfor %}
{%- endif %}

</div>
